// Embeds src/engine/harness.py into a TS module so Metro can bundle it as a
// plain string on every platform (no file-system access needed at runtime).
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const src = readFileSync(join(root, 'src/engine/harness.py'), 'utf8').replace(/\r\n/g, '\n');
const out =
  '// AUTO-GENERATED by scripts/build-harness.mjs from src/engine/harness.py. Do not edit.\n' +
  `export const HARNESS_SOURCE: string = ${JSON.stringify(src)};\n`;

const target = join(root, 'src/engine/harness.generated.ts');
let current = '';
try {
  current = readFileSync(target, 'utf8');
} catch {}
if (current !== out) {
  writeFileSync(target, out);
  console.log('harness.generated.ts updated');
}
